function csSearchScore(item, query) {
  const words = query.toLowerCase().trim().split(/\s+/).filter(Boolean);
  if (!words.length) return 0;
  const title = item.title.toLowerCase();
  const category = (item.category || '').toLowerCase();
  const desc = (item.desc || '').toLowerCase();
  const kw = (item.keywords || []).join(' ').toLowerCase();
  let score = 0;
  for (const w of words) {
    let matched = false;
    if (title.includes(w)) { score += title.startsWith(w) ? 20 : 12; matched = true; }
    if (kw.includes(w)) { score += 10; matched = true; }
    if (category.includes(w)) { score += 6; matched = true; }
    if (desc.includes(w)) { score += 3; matched = true; }
    if (!matched) return 0;
  }
  return score;
}

function searchSite(query) {
  if (!query || !query.trim()) return [];
  return SEARCH_INDEX
    .map((item) => ({ item, score: csSearchScore(item, query) }))
    .filter((r) => r.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, 7)
    .map((r) => r.item);
}

