/* ---------- hooks ---------- */

function useReveal(threshold, fallbackMs) {
  threshold = threshold == null ? 0.2 : threshold;
  fallbackMs = fallbackMs == null ? 900 : fallbackMs;
  const ref = useRef(null);
  const [revealed, setRevealed] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let done = false;
    const reveal = () => { if (!done) { done = true; setRevealed(true); } };
    let io;
    if ('IntersectionObserver' in window) {
      io = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            reveal();
            io.unobserve(entry.target);
          }
        });
      }, { threshold });
      io.observe(el);
    }
    const t = setTimeout(reveal, fallbackMs);
    return () => { if (io) io.disconnect(); clearTimeout(t); };
  }, []);
  return [ref, revealed];
}

function useCountUp(active, target, duration) {
  duration = duration == null ? 900 : duration;
  const [value, setValue] = useState(0);
  const startedRef = useRef(false);
  useEffect(() => {
    if (!active || startedRef.current) return;
    startedRef.current = true;
    const start = performance.now();
    let raf;
    const step = (t) => {
      const p = Math.min(1, (t - start) / duration);
      setValue(target * p);
      if (p < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [active]);
  return value;
}

function formatCounter(value, cfg) {
  return (cfg.prefix || '') + value.toFixed(cfg.decimals) + (cfg.suffix || '');
}

/* Counts down once from a higher number to the target when revealed, then stops — not a live/looping countdown. */
function useCountDown(active, target, duration) {
  duration = duration == null ? 1100 : duration;
  const startValue = target * 2;
  const [value, setValue] = useState(startValue);
  const startedRef = useRef(false);
  useEffect(() => {
    if (!active || startedRef.current) return;
    startedRef.current = true;
    const start = performance.now();
    let raf;
    const step = (t) => {
      const p = Math.min(1, (t - start) / duration);
      setValue(startValue - (startValue - target) * p);
      if (p < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [active]);
  return value;
}

/* ---------- small shared bits ---------- */

function Reveal({ children, style, delay, className, as }) {
  const Tag = as || 'div';
  const [ref, revealed] = useReveal();
  return (
    <Tag
      ref={ref}
      className={'reveal ' + (revealed ? 'reveal-shown' : 'reveal-hidden') + (className ? ' ' + className : '')}
      style={{ ...style, transitionDelay: delay ? delay + 's' : '0s' }}
    >
      {children}
    </Tag>
  );
}

function GradientText({ children, style }) {
  return (
    <span style={{
      background: 'linear-gradient(135deg,#8B5CF6,#3B82F6)',
      WebkitBackgroundClip: 'text', backgroundClip: 'text', color: 'transparent',
      ...style
    }}>{children}</span>
  );
}

