function TalkModal({ open, onClose }) {
  const panelRef = useRef(null);

  useEffect(() => {
    if (!open) return;
    const onKeyDown = (e) => {
      if (e.key === 'Escape') {
        onClose();
        return;
      }
      if (e.key === 'Tab' && panelRef.current) {
        const focusables = panelRef.current.querySelectorAll('a[href], button:not([disabled])');
        if (!focusables.length) return;
        const first = focusables[0];
        const last = focusables[focusables.length - 1];
        if (e.shiftKey && document.activeElement === first) {
          e.preventDefault();
          last.focus();
        } else if (!e.shiftKey && document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
      }
    };
    document.addEventListener('keydown', onKeyDown);
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    const t = setTimeout(() => { if (panelRef.current) panelRef.current.focus(); }, 10);
    return () => {
      document.removeEventListener('keydown', onKeyDown);
      document.body.style.overflow = prevOverflow;
      clearTimeout(t);
    };
  }, [open, onClose]);

  if (!open) return null;

  return ReactDOM.createPortal(
    <div className="talk-modal-backdrop" onClick={onClose} role="presentation">
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="talk-modal-heading"
        tabIndex={-1}
        onClick={(e) => e.stopPropagation()}
        className="talk-modal-panel"
      >
        <button type="button" onClick={onClose} aria-label="Close" className="talk-modal-close">✕</button>
        <div className="text-center" style={{ marginBottom: 24 }}>
          <div style={{ color: '#A78BFA', fontSize: 12, fontWeight: 700, letterSpacing: '0.1em', marginBottom: 12 }}>LET'S TALK</div>
          <div id="talk-modal-heading" style={{ fontSize: 26, fontWeight: 800, marginBottom: 8 }}>Let's build something that grows.</div>
          <div style={{ color: '#9CA3AF', fontSize: 14 }}>Choose the channel that works best for you.</div>
        </div>
        <div className="flex flex-col gap-3">
          {CONTACT_CHANNELS.map((c) => <ContactChannelCard key={c.id} c={c} />)}
        </div>
        <div className="text-center" style={{ color: '#6B7280', fontSize: 12, marginTop: 22 }}>Usually responds within 24 hours.</div>
      </div>
    </div>,
    document.body
  );
}

function useActiveSection(ids) {
  const [active, setActive] = useState(ids[0]);
  useEffect(() => {
    let ticking = false;
    const compute = () => {
      ticking = false;
      const offset = 96;
      let current = ids[0];
      let bestTop = -Infinity;
      for (const id of ids) {
        const el = document.getElementById(id);
        if (!el) continue;
        const top = el.getBoundingClientRect().top;
        if (top - offset <= 0 && top > bestTop) {
          bestTop = top;
          current = id;
        }
      }
      setActive(current);
    };
    const onScroll = () => {
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(compute);
    };
    compute();
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);
    return () => {
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onScroll);
    };
  }, [ids]);
  return active;
}

