function SearchBar({ variant }) {
  const isMobile = variant === 'mobile';
  const [query, setQuery] = useState('');
  const [open, setOpen] = useState(false);
  const [activeIdx, setActiveIdx] = useState(-1);
  const inputRef = useRef(null);
  const containerRef = useRef(null);
  const results = searchSite(query);

  useEffect(() => {
    const onKey = (e) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        if (inputRef.current) { inputRef.current.focus(); setOpen(true); }
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  useEffect(() => {
    if (!open) return;
    const onDocMouseDown = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener('mousedown', onDocMouseDown);
    return () => document.removeEventListener('mousedown', onDocMouseDown);
  }, [open]);

  const goTo = (item) => {
    setOpen(false);
    setActiveIdx(-1);
    if (inputRef.current) inputRef.current.blur();
    if (window.location.hash === '#' + item.route) {
      const el = document.getElementById(item.route);
      if (el) el.scrollIntoView({ behavior: 'smooth' });
    } else {
      window.location.hash = item.route;
    }
  };

  const onKeyDown = (e) => {
    if (e.key === 'Escape') { setOpen(false); if (inputRef.current) inputRef.current.blur(); return; }
    if (!open || results.length === 0) return;
    if (e.key === 'ArrowDown') { e.preventDefault(); setActiveIdx((i) => Math.min(results.length - 1, i + 1)); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); setActiveIdx((i) => Math.max(0, i - 1)); }
    else if (e.key === 'Enter') { e.preventDefault(); const pick = results[activeIdx] || results[0]; if (pick) goTo(pick); }
  };

  return (
    <div ref={containerRef} className={isMobile ? '' : 'hidden md:block'} style={{ position: 'relative', width: isMobile ? '100%' : 230 }}>
      <div className="flex items-center gap-2" style={{ background: '#12131C', border: '1px solid ' + (open ? 'rgba(139,92,246,0.4)' : 'rgba(255,255,255,0.08)'), borderRadius: 10, padding: '8px 12px', transition: 'border-color .15s ease' }}>
        <span style={{ color: '#6B7280', fontSize: 13, flexShrink: 0 }}>🔍</span>
        <input
          ref={inputRef}
          type="text"
          value={query}
          onChange={(e) => { setQuery(e.target.value); setOpen(true); setActiveIdx(-1); }}
          onFocus={() => setOpen(true)}
          onKeyDown={onKeyDown}
          placeholder="Search services, case studies…"
          aria-label="Search the site"
          style={{ background: 'transparent', border: 'none', outline: 'none', color: '#fff', fontSize: 12.5, width: '100%', fontFamily: 'inherit' }}
        />
        {query ? (
          <span onMouseDown={(e) => { e.preventDefault(); setQuery(''); setActiveIdx(-1); if (inputRef.current) inputRef.current.focus(); }} style={{ color: '#6B7280', fontSize: 13, cursor: 'pointer', flexShrink: 0 }}>✕</span>
        ) : (
          <span style={{ marginLeft: 4, background: '#1A1B26', borderRadius: 5, padding: '2px 6px', fontSize: 11, color: '#6B7280', flexShrink: 0 }}>⌘K</span>
        )}
      </div>

      {open && query.trim() ? (
        <div style={{ position: 'absolute', top: 'calc(100% + 8px)', left: 0, width: isMobile ? '100%' : 340, maxHeight: 380, overflowY: 'auto', background: '#12131C', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 14, boxShadow: '0 20px 50px rgba(0,0,0,0.5)', padding: 8, zIndex: 60 }}>
          {results.length ? (
            results.map((item, i) => (
              <SearchResultRow key={item.id} item={item} active={i === activeIdx} onSelect={goTo} />
            ))
          ) : (
            <div style={{ padding: '18px 14px', textAlign: 'center', color: '#6B7280', fontSize: 13 }}>No results for "{query}"</div>
          )}
        </div>
      ) : null}
    </div>
  );
}

