function SnapshotPanel({ revealed }) {
  const gaugeValue = useCountUp(revealed, COUNTERS.gauge.target);
  const gaugeOffset = CIRC * (1 - gaugeValue / 100);
  return (
    <div className="grid grid-cols-1 md:grid-cols-[340px_1fr] gap-8" style={{ background: '#12131C', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 20, padding: 36 }}>
      <div className="flex flex-col items-center justify-center md:border-r" style={{ borderColor: 'rgba(255,255,255,0.08)', paddingRight: 0 }}>
        <svg width="180" height="180" viewBox="0 0 180 180">
          <circle cx="90" cy="90" r="78" fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth="14" />
          <circle cx="90" cy="90" r="78" fill="none" stroke="url(#gaugeGrad)" strokeWidth="14" strokeLinecap="round"
            transform="rotate(-90 90 90)"
            style={{ strokeDasharray: CIRC, strokeDashoffset: gaugeOffset, transition: 'stroke-dashoffset 0.1s linear' }} />
          <defs><linearGradient id="gaugeGrad" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stopColor="#8B5CF6" /><stop offset="100%" stopColor="#3B82F6" /></linearGradient></defs>
          <text x="90" y="84" textAnchor="middle" fill="#fff" fontSize="34" fontWeight="800">{Math.round(gaugeValue)}</text>
          <text x="90" y="108" textAnchor="middle" fill="#6B7280" fontSize="12">/100</text>
        </svg>
        <div style={{ marginTop: 10, background: 'rgba(74,222,128,0.1)', color: '#4ADE80', border: '1px solid rgba(74,222,128,0.3)', padding: '6px 14px', borderRadius: 999, fontSize: 12, fontWeight: 700 }}>Above Average</div>
      </div>
      <div>
        <div style={{ fontWeight: 700, fontSize: 14, color: '#9CA3AF', letterSpacing: '0.05em', marginBottom: 14 }}>PRIORITY RECOMMENDATIONS</div>
        {RECOMMENDATIONS.map((r, i) => (
          <div key={i} className="flex items-center justify-between" style={{ padding: '12px 0', borderTop: '1px solid rgba(255,255,255,0.06)' }}>
            <div className="flex items-center gap-2.5"><span style={{ width: 8, height: 8, borderRadius: '50%', background: r.color }} /><span style={{ fontSize: 14, color: '#E5E7EB' }}>{r.title}</span></div>
            <span style={{ fontSize: 14, fontWeight: 700, color: '#4ADE80' }}>{r.impact}</span>
          </div>
        ))}
        <div className="flex gap-3.5 items-start" style={{ marginTop: 20, background: 'rgba(255,255,255,0.03)', borderRadius: 12, padding: 16 }}>
          <div style={{ width: 34, height: 34, borderRadius: '50%', background: 'linear-gradient(135deg,#8B5CF6,#3B82F6)', flexShrink: 0 }} />
          <div style={{ fontSize: 13, color: '#9CA3AF', lineHeight: 1.6 }}>Based on this snapshot, fixing checkout friction and email retention alone could recover roughly <b style={{ color: '#fff' }}>$8,000–$14,000/mo</b> in lost revenue.</div>
        </div>
      </div>
    </div>
  );
}

