function WebsiteScoreGauge({ revealed }) {
  const scoreValue = useCountUp(revealed, WEBSITE_OVERALL_SCORE.value);
  const offset = CIRC * (1 - scoreValue / 100);
  return (
    <div className="flex flex-col items-center justify-center">
      <svg width="200" height="200" viewBox="0 0 180 180">
        <circle cx="90" cy="90" r="78" fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth="14" />
        <circle cx="90" cy="90" r="78" fill="none" stroke="url(#gaugeGradWebsite)" strokeWidth="14" strokeLinecap="round"
          transform="rotate(-90 90 90)"
          style={{ strokeDasharray: CIRC, strokeDashoffset: offset, transition: 'stroke-dashoffset 0.1s linear' }} />
        <defs><linearGradient id="gaugeGradWebsite" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stopColor="#8B5CF6" /><stop offset="100%" stopColor="#3B82F6" /></linearGradient></defs>
        <text x="90" y="84" textAnchor="middle" fill="#fff" fontSize="34" fontWeight="800">{Math.round(scoreValue)}</text>
        <text x="90" y="108" textAnchor="middle" fill="#6B7280" fontSize="12">/100</text>
      </svg>
      <div style={{ marginTop: 10, background: 'rgba(74,222,128,0.1)', color: '#4ADE80', border: '1px solid rgba(74,222,128,0.3)', padding: '6px 14px', borderRadius: 999, fontSize: 12, fontWeight: 700 }}>{WEBSITE_OVERALL_SCORE.label}</div>
    </div>
  );
}

