function Calculator() {
  const [ref, revealed] = useReveal();
  const [activeCalcStep, setActiveCalcStep] = useState(CALC_STEPS.length - 1);
  const activeLabel = CALC_STEPS[activeCalcStep];
  return (
    <div id="store-growth" ref={ref} className={'reveal ' + (revealed ? 'reveal-shown' : 'reveal-hidden')} style={{ maxWidth: 1200, margin: '0 auto', padding: '70px 24px' }}>
      <div className="text-center" style={{ maxWidth: 640, margin: '0 auto 40px' }}>
        <h2 style={{ fontSize: 34, fontWeight: 800, marginBottom: 12 }}>Discover Your Store's <GradientText>Growth Potential</GradientText></h2>
        <div style={{ color: '#9CA3AF', fontSize: 15 }}>A quick snapshot of where your store stands — and what's costing you revenue right now.</div>
      </div>
      <div className="flex justify-between flex-wrap gap-3" style={{ marginBottom: 44, padding: '0 10px' }}>
        {CALC_STEPS.map((label, i) => {
          const active = i === activeCalcStep;
          return (
            <div key={label} onClick={() => setActiveCalcStep(i)} className="flex flex-col items-center gap-2" style={{ flex: 1, minWidth: 60, cursor: 'pointer' }}>
              <div style={{
                width: 34, height: 34, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center',
                fontSize: 14, fontWeight: 700,
                background: active ? 'linear-gradient(135deg,#8B5CF6,#3B82F6)' : '#1A1B26',
                color: active ? '#fff' : '#6B7280',
                border: active ? 'none' : '1px solid rgba(255,255,255,0.1)'
              }}>{i + 1}</div>
              <div style={{ fontSize: 11, color: active ? '#C4B5FD' : '#6B7280', fontWeight: 600, textAlign: 'center' }}>{label}</div>
            </div>
          );
        })}
      </div>
      <div key={activeCalcStep} className="fade-panel">
        {activeLabel === 'Snapshot' ? <SnapshotPanel revealed={revealed} /> : activeLabel === 'Strategy' ? <StrategyPanel /> : activeLabel === 'Traffic' ? <TrafficPanel revealed={revealed} /> : activeLabel === 'Revenue' ? <RevenuePanel revealed={revealed} /> : activeLabel === 'Product' ? <ProductPanel revealed={revealed} /> : activeLabel === 'Ads' ? <AdsPanel revealed={revealed} /> : activeLabel === 'Website' ? <WebsitePanel revealed={revealed} /> : <CalcStepStub label={activeLabel} />}
      </div>
      <div className="text-center" style={{ marginTop: 50 }}>
        <div style={{ fontSize: 28, fontWeight: 800, marginBottom: 22 }}>Ready To Turn This Strategy <GradientText>Into Results?</GradientText></div>
        <div className="flex flex-wrap gap-3.5 justify-center">
          <a href={CALENDLY_URL} target="_blank" rel="noopener noreferrer" className="btn-primary" style={{ background: 'linear-gradient(135deg,#8B5CF6,#3B82F6)', color: '#fff', padding: '14px 24px', borderRadius: 999, fontWeight: 700, fontSize: 14, boxShadow: '0 0 26px rgba(139,92,246,0.35)' }}>Book a Strategy Call →</a>
          <a href="#case-studies" className="btn-outline" style={{ border: '1px solid rgba(255,255,255,0.16)', color: '#fff', padding: '14px 24px', borderRadius: 999, fontWeight: 700, fontSize: 14 }}>View Case Studies</a>
          <a href="#services" className="btn-outline" style={{ border: '1px solid rgba(255,255,255,0.16)', color: '#fff', padding: '14px 24px', borderRadius: 999, fontWeight: 700, fontSize: 14 }}>See Services</a>
        </div>
      </div>
    </div>
  );
}

