function SignalLightbox({ items, index, onClose, onNav }) {
  const s = items[index];
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === 'Escape') onClose();
      if (e.key === 'ArrowLeft') onNav(-1);
      if (e.key === 'ArrowRight') onNav(1);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose, onNav]);

  return ReactDOM.createPortal(
    <div onClick={onClose} style={{ position: 'fixed', inset: 0, background: 'rgba(6,6,10,0.92)', backdropFilter: 'blur(6px)', zIndex: 200, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 24, cursor: 'zoom-out' }}>
      <div onClick={(e) => e.stopPropagation()} className="flex flex-col lg:flex-row" style={{ maxWidth: 1000, maxHeight: '88vh', width: '100%', background: '#12131C', border: '1px solid rgba(255,255,255,0.1)', borderRadius: 16, overflowY: 'auto', overflowX: 'hidden', cursor: 'default' }}>
        <div style={{ background: '#0A0A0F', flex: '1 1 auto', display: 'flex', justifyContent: 'center', minWidth: 0 }}>
          <img src={s.fullImg} alt={s.alt} style={{ maxWidth: '100%', maxHeight: '70vh', display: 'block' }} />
        </div>
        <div style={{ padding: 32, flex: '0 0 auto', width: '100%', maxWidth: 340 }}>
          <div className="flex items-center gap-2" style={{ marginBottom: 12 }}>
            <span style={{ color: '#A78BFA', fontSize: 11, fontWeight: 700, letterSpacing: '0.08em' }}>{s.category}</span>
            <span style={{ color: '#4B5563', fontSize: 11 }}>•</span>
            <span style={{ color: '#6B7280', fontSize: 10.5, fontWeight: 600, letterSpacing: '0.06em' }}>{s.platform}</span>
          </div>
          <div style={{ fontWeight: 800, fontSize: 22, marginBottom: 6, color: '#fff' }}>{s.title}</div>
          <div style={{ color: '#6B7280', fontSize: 12.5, marginBottom: 16 }}>{s.person}{s.context ? ' — ' + s.context : ''}</div>
          <div style={{ color: '#9CA3AF', fontSize: 13.5, lineHeight: 1.65, marginBottom: s.quote ? 16 : 0 }}>{s.description}</div>
          {s.quote ? (
            <div style={{ borderLeft: '2px solid #8B5CF6', background: 'rgba(139,92,246,0.06)', borderRadius: '0 8px 8px 0', padding: '12px 16px' }}>
              <div style={{ color: '#D1D5DB', fontSize: 13.5, fontStyle: 'italic', lineHeight: 1.55 }}>&ldquo;{s.quote}&rdquo;</div>
            </div>
          ) : null}
        </div>
      </div>

      <button onClick={(e) => { e.stopPropagation(); onNav(-1); }} aria-label="Previous conversation" style={{ position: 'absolute', left: 20, top: '50%', transform: 'translateY(-50%)', width: 44, height: 44, borderRadius: '50%', background: 'rgba(255,255,255,0.08)', border: '1px solid rgba(255,255,255,0.16)', color: '#fff', fontSize: 18, cursor: 'pointer' }}>‹</button>
      <button onClick={(e) => { e.stopPropagation(); onNav(1); }} aria-label="Next conversation" style={{ position: 'absolute', right: 20, top: '50%', transform: 'translateY(-50%)', width: 44, height: 44, borderRadius: '50%', background: 'rgba(255,255,255,0.08)', border: '1px solid rgba(255,255,255,0.16)', color: '#fff', fontSize: 18, cursor: 'pointer' }}>›</button>
      <button onClick={onClose} aria-label="Close" style={{ position: 'absolute', top: 20, right: 20, width: 40, height: 40, borderRadius: '50%', background: 'rgba(255,255,255,0.08)', border: '1px solid rgba(255,255,255,0.16)', color: '#fff', fontSize: 18, cursor: 'pointer' }}>✕</button>
    </div>,
    document.body
  );
}

function ClientSignals() {
  const [ref, revealed] = useReveal();
  const [openIndex, setOpenIndex] = useState(null);
  const featured = CLIENT_SIGNALS.filter((s) => s.featured);
  const supporting = CLIENT_SIGNALS.filter((s) => !s.featured);

  return (
    <div id="client-signals" ref={ref} className={'reveal ' + (revealed ? 'reveal-shown' : 'reveal-hidden')} style={{ maxWidth: 1300, margin: '0 auto', padding: '70px 24px' }}>
      <div className="text-center" style={{ maxWidth: 640, margin: '0 auto 44px' }}>
        <div style={{ color: '#A78BFA', fontSize: 12, fontWeight: 700, letterSpacing: '0.1em', marginBottom: 12 }}>CLIENT SIGNALS</div>
        <h2 style={{ fontSize: 34, fontWeight: 800, marginBottom: 12 }}>Real Conversations. <GradientText>Real Trust.</GradientText></h2>
        <div style={{ color: '#9CA3AF', fontSize: 15 }}>Behind every project is a real conversation. Here are selected interactions with clients, store owners and ecommerce professionals who trusted my expertise, discussed projects with me, or shared feedback about how I work.</div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {featured.map((s) => (
          <ClientSignalCard key={s.id} s={s} featured onOpen={() => setOpenIndex(CLIENT_SIGNALS.findIndex((x) => x.id === s.id))} />
        ))}
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6" style={{ marginTop: 24 }}>
        {supporting.map((s) => (
          <ClientSignalCard key={s.id} s={s} onOpen={() => setOpenIndex(CLIENT_SIGNALS.findIndex((x) => x.id === s.id))} />
        ))}
      </div>

      <div className="text-center" style={{ marginTop: 30 }}>
        <div style={{ color: '#6B7280', fontSize: 12 }}>Selected conversations — shared as captured, with identifying details limited where appropriate.</div>
      </div>

      <div style={{ marginTop: 46, background: '#12131C', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 20, padding: 40, textAlign: 'center' }}>
        <div style={{ fontSize: 20, fontWeight: 700, marginBottom: 24, color: '#D1D5DB' }}>Trust is earned before a project begins — and strengthened by the results that follow.</div>
        <div className="flex flex-wrap items-center justify-center gap-3">
          <a href="#case-studies" className="btn-outline inline-block" style={{ border: '1px solid rgba(255,255,255,0.16)', color: '#fff', padding: '14px 26px', borderRadius: 999, fontWeight: 700, fontSize: 14 }}>Explore Case Studies</a>
          <a href={CALENDLY_URL} target="_blank" rel="noopener noreferrer" className="btn-primary inline-block" style={{ background: 'linear-gradient(135deg,#8B5CF6,#3B82F6)', color: '#fff', padding: '14px 26px', borderRadius: 999, fontWeight: 700, fontSize: 14, boxShadow: '0 0 26px rgba(139,92,246,0.35)' }}>Book a Strategy Call →</a>
        </div>
      </div>

      {openIndex !== null ? (
        <SignalLightbox
          items={CLIENT_SIGNALS}
          index={openIndex}
          onClose={() => setOpenIndex(null)}
          onNav={(dir) => setOpenIndex((i) => (i + dir + CLIENT_SIGNALS.length) % CLIENT_SIGNALS.length)}
        />
      ) : null}
    </div>
  );
}

/* ---------- process / blueprint ---------- */

function BpMetricCard({ m, revealed }) {
  const isText = typeof m.value === 'string';
  const v = useCountUp(revealed, isText ? 0 : m.value);
  return (
    <div style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 14, padding: '20px 16px', textAlign: 'center' }}>
      <div style={{ fontSize: isText ? 20 : 24, fontWeight: 800, marginBottom: 4 }}>{isText ? m.value : formatCounter(v, m)}</div>
      <div style={{ color: '#9CA3AF', fontSize: 11 }}>{m.label}</div>
    </div>
  );
}

function BpAnalyzeList({ items }) {
  return (
    <div>
      <div style={{ color: '#A78BFA', fontSize: 12, fontWeight: 700, letterSpacing: '0.08em', marginBottom: 14 }}>WHAT I ANALYZE</div>
      {items.map((it, i) => (
        <div key={i} className="flex items-start gap-2.5" style={{ marginBottom: 10 }}>
          <span style={{ color: '#4ADE80', fontSize: 13, marginTop: 1, flexShrink: 0 }}>✓</span>
          <span style={{ color: '#D1D5DB', fontSize: 13, lineHeight: 1.5 }}>{it}</span>
        </div>
      ))}
    </div>
  );
}

function BpBulletCard({ c }) {
  return (
    <div style={{ background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.06)', borderRadius: 14, padding: 20 }}>
      <div style={{ fontWeight: 800, fontSize: 14, marginBottom: 8, color: '#fff' }}>{c.title}</div>
      {c.desc ? <div style={{ color: '#9CA3AF', fontSize: 12.5, lineHeight: 1.5, marginBottom: c.items ? 10 : 0 }}>{c.desc}</div> : null}
      {c.items ? (
        <div>
          {c.items.map((it) => (
            <div key={it} className="flex items-center gap-2" style={{ color: '#D1D5DB', fontSize: 12.5, marginBottom: 5 }}><span style={{ color: '#60A5FA' }}>•</span>{it}</div>
          ))}
        </div>
      ) : null}
    </div>
  );
}

/* ---------- blueprint: 01 store audit ---------- */

function BpAuditVisual() {
  return (
    <div style={{ background: '#0D0E15', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 16, overflow: 'hidden' }}>
      <div className="flex items-center gap-2" style={{ padding: '12px 16px', background: '#15161F', borderBottom: '1px solid rgba(255,255,255,0.06)' }}>
        <span style={{ width: 10, height: 10, borderRadius: '50%', background: '#F87171' }} />
        <span style={{ width: 10, height: 10, borderRadius: '50%', background: '#FBBF24' }} />
        <span style={{ width: 10, height: 10, borderRadius: '50%', background: '#4ADE80' }} />
        <span style={{ marginLeft: 10, color: '#6B7280', fontSize: 11, background: '#1A1B26', borderRadius: 6, padding: '3px 10px' }}>store.myshopify.com</span>
      </div>
      <div style={{ padding: 20 }}>
        {BP_AUDIT_ROWS.map((r, i) => {
          const toneColor = r.tone === 'good' ? '#4ADE80' : r.tone === 'bad' ? '#F87171' : '#FBBF24';
          return (
            <div key={r.label} className="flex items-center justify-between" style={{ padding: '12px 0', borderTop: i ? '1px solid rgba(255,255,255,0.06)' : 'none' }}>
              <div className="flex items-center gap-2.5">
                <span style={{ width: 8, height: 8, borderRadius: '50%', background: toneColor, flexShrink: 0 }} />
                <span style={{ color: '#D1D5DB', fontSize: 13, fontWeight: 600 }}>{r.label}</span>
              </div>
              <span style={{ color: toneColor, fontSize: 13, fontWeight: 700 }}>{r.value}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function BPAuditPanel({ revealed }) {
  return (
    <div>
      <div style={{ color: '#60A5FA', fontSize: 12, fontWeight: 700, letterSpacing: '0.1em', marginBottom: 14 }}>TECHNICAL DIAGNOSTICS</div>
      <div style={{ fontSize: 26, fontWeight: 800, lineHeight: 1.3, marginBottom: 14 }}>Your Store Can't Grow Until You Know What's Holding It Back</div>
      <p style={{ color: '#9CA3AF', fontSize: 14, lineHeight: 1.7, marginBottom: 32 }}>Before improving performance, I diagnose the technical and UX foundation. Speed bottlenecks, broken mobile layouts, missing trust signals, and navigation dead-ends can silently destroy revenue every day.</p>
      <div className="grid grid-cols-1 lg:grid-cols-[1fr_260px] gap-8" style={{ marginBottom: 40 }}>
        <BpAuditVisual />
        <BpAnalyzeList items={BP_AUDIT_ANALYZE} />
      </div>
      <div style={{ fontWeight: 700, fontSize: 13, color: '#9CA3AF', letterSpacing: '0.05em', marginBottom: 16 }}>IMPACT DASHBOARD</div>
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4" style={{ marginBottom: 28 }}>
        {BP_AUDIT_IMPACT.map((m) => <BpMetricCard key={m.label} m={m} revealed={revealed} />)}
      </div>
      <a href="#contact" style={{ color: '#60A5FA', fontSize: 13, fontWeight: 700 }}>See this applied to your store →</a>
    </div>
  );
}

/* ---------- blueprint: 02 conversion analysis ---------- */

function BpFunnelBars({ data }) {
  return (
    <div className="flex flex-col items-center" style={{ gap: 6 }}>
      {data.map((f, i) => (
        <React.Fragment key={f.label}>
          {i > 0 && f.dropoff ? (
            <div style={{ textAlign: 'center' }}>
              {f.biggest ? <div style={{ fontSize: 10, fontWeight: 800, color: '#F87171', letterSpacing: '0.06em', marginBottom: 2 }}>BIGGEST DROP-OFF</div> : null}
              <div style={{ fontSize: f.biggest ? 13 : 11, fontWeight: 700, color: f.biggest ? '#F87171' : '#9CA3AF' }}>↓ {f.dropoff}</div>
            </div>
          ) : null}
          <div className="flex items-center justify-between gap-3" style={{
            width: f.pct + '%', maxWidth: 460, minWidth: 210, boxSizing: 'border-box', borderRadius: 10, padding: '12px 20px',
            background: f.biggest ? 'rgba(248,113,113,0.14)' : 'rgba(139,92,246,0.12)',
            border: '1px solid ' + (f.biggest ? 'rgba(248,113,113,0.4)' : 'rgba(139,92,246,0.25)')
          }}>
            <span style={{ fontSize: 13, fontWeight: 700, color: '#fff' }}>{f.label}</span>
            <span style={{ fontSize: 13, fontWeight: 700, color: f.biggest ? '#F87171' : '#C4B5FD' }}>{f.pct}%</span>
          </div>
        </React.Fragment>
      ))}
    </div>
  );
}

function BPConversionPanel({ revealed }) {
  return (
    <div>
      <div style={{ color: '#60A5FA', fontSize: 12, fontWeight: 700, letterSpacing: '0.1em', marginBottom: 14 }}>CONVERSION INTELLIGENCE</div>
      <div style={{ fontSize: 26, fontWeight: 800, lineHeight: 1.3, marginBottom: 14 }}>Traffic Doesn't Matter If Your Store Can't Convert It</div>
      <p style={{ color: '#9CA3AF', fontSize: 14, lineHeight: 1.7, marginBottom: 32 }}>I analyze exactly where visitors hesitate, abandon, or fail to complete the purchase — then trace each drop-off back to its real cause, whether that's messaging, trust, friction, or price shock.</p>
      <div className="grid grid-cols-1 lg:grid-cols-[1fr_260px] gap-8" style={{ marginBottom: 32 }}>
        <BpFunnelBars data={BP_CONVERSION_FUNNEL} />
        <BpAnalyzeList items={BP_CONVERSION_ANALYZE} />
      </div>
      <div style={{ fontWeight: 700, fontSize: 13, color: '#9CA3AF', letterSpacing: '0.05em', marginBottom: 6 }}>CONVERSION IMPACT</div>
      <div style={{ color: '#6B7280', fontSize: 12, marginBottom: 16 }}>Estimated/demo opportunities based on typical funnel performance — not guaranteed or verified results.</div>
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4" style={{ marginBottom: 28 }}>
        {BP_CONVERSION_IMPACT.map((m) => <BpMetricCard key={m.label} m={m} revealed={revealed} />)}
      </div>
      <div className="text-center" style={{ padding: 16, background: 'rgba(139,92,246,0.06)', border: '1px solid rgba(139,92,246,0.2)', borderRadius: 12, color: '#C4B5FD', fontSize: 13, fontWeight: 700 }}>Find the friction → Fix the leak → Increase conversion</div>
    </div>
  );
}

/* ---------- blueprint: 03 customer journey ---------- */

function BpJourneyStep({ s, active, onClick }) {
  return (
    <div onClick={onClick} className="bp-journey-pill" style={{
      cursor: 'pointer', flexShrink: 0, padding: '10px 16px', borderRadius: 999, fontSize: 13, fontWeight: 700, whiteSpace: 'nowrap',
      background: active ? 'linear-gradient(135deg,#8B5CF6,#3B82F6)' : (s.major ? 'rgba(248,113,113,0.1)' : '#1A1B26'),
      border: '1px solid ' + (active ? 'transparent' : (s.major ? 'rgba(248,113,113,0.35)' : 'rgba(255,255,255,0.08)')),
      color: active ? '#fff' : (s.major ? '#F87171' : '#9CA3AF')
    }}>{s.label}</div>
  );
}

function BpJourneyMap() {
  const [activeStage, setActiveStage] = useState('product');
  const current = BP_JOURNEY_STAGES.find((s) => s.id === activeStage);
  return (
    <div>
      <div className="flex items-center flex-wrap" style={{ gap: 8, marginBottom: 24 }}>
        {BP_JOURNEY_STAGES.map((s, i) => (
          <React.Fragment key={s.id}>
            <BpJourneyStep s={s} active={s.id === activeStage} onClick={() => setActiveStage(s.id)} />
            {i < BP_JOURNEY_STAGES.length - 1 ? <span style={{ color: '#4B5563', flexShrink: 0 }}>→</span> : null}
          </React.Fragment>
        ))}
      </div>
      <div key={activeStage} className="fade-panel" style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 14, padding: 22 }}>
        <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: '0.08em', color: '#A78BFA', marginBottom: 4 }}>{current.label.toUpperCase()}</div>
        <div style={{ color: '#D1D5DB', fontSize: 13, fontWeight: 600, marginBottom: 14 }}>{current.intent}</div>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div>
            <div style={{ color: '#F87171', fontSize: 11, fontWeight: 800, letterSpacing: '0.06em', marginBottom: 6 }}>FRICTION</div>
            <div style={{ color: '#E5E7EB', fontSize: 13, lineHeight: 1.5 }}>{current.friction}</div>
          </div>
          <div>
            <div style={{ color: '#4ADE80', fontSize: 11, fontWeight: 800, letterSpacing: '0.06em', marginBottom: 6 }}>OPPORTUNITY</div>
            <div style={{ color: '#E5E7EB', fontSize: 13, lineHeight: 1.5 }}>{current.opportunity}</div>
          </div>
        </div>
      </div>
    </div>
  );
}

function BPJourneyPanel({ revealed }) {
  return (
    <div>
      <div style={{ color: '#60A5FA', fontSize: 12, fontWeight: 700, letterSpacing: '0.1em', marginBottom: 14 }}>CUSTOMER JOURNEY MAPPING</div>
      <div style={{ fontSize: 26, fontWeight: 800, lineHeight: 1.3, marginBottom: 14 }}>Every Click Is Part of the Buying Decision</div>
      <p style={{ color: '#9CA3AF', fontSize: 14, lineHeight: 1.7, marginBottom: 32 }}>I map the customer's full path from first interaction to purchase — click by click — to find exactly where intent breaks down into hesitation, and where hesitation breaks down into abandonment. Click a stage below to see what's happening at each step.</p>
      <BpJourneyMap />
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4" style={{ margin: '32px 0 28px' }}>
        {BP_JOURNEY_METRICS.map((m) => <BpMetricCard key={m.label} m={m} revealed={revealed} />)}
      </div>
      <div className="text-center" style={{ padding: 16, background: 'rgba(139,92,246,0.06)', border: '1px solid rgba(139,92,246,0.2)', borderRadius: 12, color: '#C4B5FD', fontSize: 13, fontWeight: 700 }}>I optimize the journey, not just individual pages.</div>
    </div>
  );
}

/* ---------- blueprint: 04 revenue optimization ---------- */

function BpRevenueEquation() {
  return (
    <div className="flex items-center justify-center flex-wrap" style={{ gap: 12 }}>
      {BP_REVENUE_FACTORS.map((f, i) => (
        <React.Fragment key={f}>
          {i > 0 ? <span style={{ color: '#6B7280', fontSize: 18, fontWeight: 700 }}>×</span> : null}
          <div style={{ background: 'rgba(139,92,246,0.1)', border: '1px solid rgba(139,92,246,0.3)', borderRadius: 12, padding: '14px 18px', fontSize: 13, fontWeight: 700, color: '#C4B5FD', textAlign: 'center' }}>{f}</div>
        </React.Fragment>
      ))}
      <span style={{ color: '#6B7280', fontSize: 18, fontWeight: 700 }}>=</span>
      <div style={{ background: 'linear-gradient(135deg,#8B5CF6,#3B82F6)', borderRadius: 12, padding: '14px 22px', fontSize: 14, fontWeight: 800, color: '#fff', textAlign: 'center' }}>Revenue</div>
    </div>
  );
}

function BPRevenuePanel({ revealed }) {
  return (
    <div>
      <div style={{ color: '#60A5FA', fontSize: 12, fontWeight: 700, letterSpacing: '0.1em', marginBottom: 14 }}>REVENUE INTELLIGENCE</div>
      <div style={{ fontSize: 26, fontWeight: 800, lineHeight: 1.3, marginBottom: 14 }}>More Traffic Isn't Always the Answer</div>
      <p style={{ color: '#9CA3AF', fontSize: 14, lineHeight: 1.7, marginBottom: 32 }}>Revenue is a function of more than traffic. Often the fastest, cheapest growth comes from improving the economics and conversion performance of the traffic you already have — before spending more to acquire new visitors.</p>
      <div style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 16, padding: 28, marginBottom: 36 }}>
        <BpRevenueEquation />
      </div>
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4" style={{ marginBottom: 36 }}>
        {BP_REVENUE_CARDS.map((c) => <BpBulletCard key={c.title} c={c} />)}
      </div>
      <div style={{ fontWeight: 700, fontSize: 13, color: '#9CA3AF', letterSpacing: '0.05em', marginBottom: 6 }}>REVENUE OPPORTUNITY DASHBOARD</div>
      <div style={{ color: '#6B7280', fontSize: 12, marginBottom: 16 }}>Illustrative/demo figures — not guaranteed or verified results.</div>
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {BP_REVENUE_OPPORTUNITY.map((m) => <BpMetricCard key={m.label} m={m} revealed={revealed} />)}
      </div>
    </div>
  );
}

/* ---------- blueprint: 05 scaling strategy ---------- */

function BpProgressionRow() {
  return (
    <div className="flex items-stretch flex-wrap lg:flex-nowrap" style={{ gap: 14 }}>
      {BP_SCALING_STAGES.map((s, i) => (
        <React.Fragment key={s.title}>
          <div style={{ flex: '1 1 220px', minWidth: 200 }}><BpBulletCard c={s} /></div>
          {i < BP_SCALING_STAGES.length - 1 ? (
            <div className="hidden lg:flex items-center justify-center" style={{ color: '#6B7280', fontSize: 20, fontWeight: 700, flexShrink: 0 }}>→</div>
          ) : null}
        </React.Fragment>
      ))}
    </div>
  );
}

function BpReadinessGauge({ revealed }) {
  const v = useCountUp(revealed, BP_SCALE_READINESS.value);
  const offset = CIRC * (1 - v / 100);
  return (
    <svg width="180" height="180" viewBox="0 0 180 180">
      <circle cx="90" cy="90" r="78" fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth="14" />
      <circle cx="90" cy="90" r="78" fill="none" stroke="url(#gaugeGradBP)" strokeWidth="14" strokeLinecap="round"
        transform="rotate(-90 90 90)"
        style={{ strokeDasharray: CIRC, strokeDashoffset: offset, transition: 'stroke-dashoffset 0.1s linear' }} />
      <defs><linearGradient id="gaugeGradBP" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stopColor="#8B5CF6" /><stop offset="100%" stopColor="#3B82F6" /></linearGradient></defs>
      <text x="90" y="84" textAnchor="middle" fill="#fff" fontSize="30" fontWeight="800">{Math.round(v)}</text>
      <text x="90" y="108" textAnchor="middle" fill="#6B7280" fontSize="11">/100</text>
    </svg>
  );
}

function BPScalingPanel({ revealed }) {
  return (
    <div>
      <div style={{ color: '#60A5FA', fontSize: 12, fontWeight: 700, letterSpacing: '0.1em', marginBottom: 14 }}>GROWTH STRATEGY</div>
      <div style={{ fontSize: 26, fontWeight: 800, lineHeight: 1.3, marginBottom: 14 }}>Fix the Foundation Before You Scale the Traffic</div>
      <p style={{ color: '#9CA3AF', fontSize: 14, lineHeight: 1.7, marginBottom: 32 }}>Scaling acquisition before fixing conversion, UX, tracking, and retention doesn't scale growth — it scales inefficiency. Every dollar spent on traffic gets amplified by whatever state your store is already in, good or bad.</p>
      <div style={{ fontWeight: 700, fontSize: 13, color: '#9CA3AF', letterSpacing: '0.05em', marginBottom: 16 }}>GROWTH PROGRESSION</div>
      <div style={{ marginBottom: 40 }}><BpProgressionRow /></div>
      <div className="grid grid-cols-1 md:grid-cols-[180px_1fr] gap-8 items-center" style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 16, padding: 28, marginBottom: 28 }}>
        <div className="flex flex-col items-center">
          <BpReadinessGauge revealed={revealed} />
          <div style={{ marginTop: 4, color: '#9CA3AF', fontSize: 12, fontWeight: 700, letterSpacing: '0.06em' }}>SCALE READINESS</div>
        </div>
        <div>
          {BP_SCALE_CATEGORIES.map((c) => <WebsiteCategoryBar key={c.label} c={c} revealed={revealed} />)}
        </div>
      </div>
      <a href="#contact" style={{ color: '#60A5FA', fontSize: 13, fontWeight: 700 }}>See the growth roadmap →</a>
    </div>
  );
}

