/* ---------- blueprint: left nav + wrapper ---------- */

function BpNavCard({ s, active, onClick, compact }) {
  return (
    <div onClick={onClick} className={'bp-nav-card' + (active ? ' bp-nav-card-active' : '') + (compact ? ' bp-nav-card-compact' : '')}>
      <span style={{ color: active ? '#C4B5FD' : '#6B7280', fontSize: 11, fontWeight: 800, letterSpacing: '0.05em', flexShrink: 0 }}>{s.num}</span>
      <div className="bp-nav-icon">{s.icon}</div>
      <span style={{ fontSize: 14, fontWeight: 700, color: active ? '#fff' : '#9CA3AF', whiteSpace: compact ? 'nowrap' : 'normal' }}>{s.title}</span>
    </div>
  );
}

function Process() {
  const [ref, revealed] = useReveal();
  const [activeStage, setActiveStage] = useState(BP_STAGES[0].id);

  const renderPanel = () => {
    if (activeStage === 'audit') return <BPAuditPanel revealed={revealed} />;
    if (activeStage === 'conversion') return <BPConversionPanel revealed={revealed} />;
    if (activeStage === 'journey') return <BPJourneyPanel revealed={revealed} />;
    if (activeStage === 'revenue') return <BPRevenuePanel revealed={revealed} />;
    if (activeStage === 'scaling') return <BPScalingPanel revealed={revealed} />;
    return <BPAutomationPanel revealed={revealed} />;
  };

  return (
    <div id="blueprint" ref={ref} className={'reveal ' + (revealed ? 'reveal-shown' : 'reveal-hidden')} style={{ maxWidth: 1300, margin: '0 auto', padding: '70px 24px' }}>
      <div className="text-center" style={{ maxWidth: 640, margin: '0 auto 40px' }}>
        <div style={{ color: '#A78BFA', fontSize: 12, fontWeight: 700, letterSpacing: '0.1em', marginBottom: 12 }}>HOW I'D BECOME YOUR PARTNER</div>
        <h2 style={{ fontSize: 34, fontWeight: 800, marginBottom: 12 }}>Inside Emmanuel's <GradientText>Shopify Growth Blueprint</GradientText></h2>
        <div style={{ color: '#9CA3AF', fontSize: 15 }}>A repeatable system, not guesswork — audit, analyze, map, optimize, scale, and automate.</div>
      </div>

      <div className="lg:hidden flex gap-3 overflow-x-auto" style={{ marginBottom: 20, paddingBottom: 4 }}>
        {BP_STAGES.map((s) => (
          <BpNavCard key={s.id} s={s} active={s.id === activeStage} onClick={() => setActiveStage(s.id)} compact />
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-[300px_1fr] gap-8">
        <div className="hidden lg:flex lg:flex-col gap-3">
          {BP_STAGES.map((s) => (
            <BpNavCard key={s.id} s={s} active={s.id === activeStage} onClick={() => setActiveStage(s.id)} />
          ))}
        </div>
        <div key={activeStage} className="fade-panel" style={{ background: '#12131C', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 20, padding: 36 }}>
          {renderPanel()}
        </div>
      </div>

      <div style={{ marginTop: 50, background: '#12131C', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 20, padding: 40, textAlign: 'center' }}>
        <div style={{ fontSize: 24, fontWeight: 800, marginBottom: 14 }}>Every High-Performing Shopify Store Follows A Proven Growth System</div>
        <div style={{ color: '#9CA3AF', fontSize: 14, maxWidth: 620, margin: '0 auto 24px' }}>This blueprint isn't theory — it's the same sequence applied across every store I've worked with, adapted to where you are today.</div>
        <a href={CALENDLY_URL} target="_blank" rel="noopener noreferrer" className="btn-primary inline-block" style={{ background: 'linear-gradient(135deg,#8B5CF6,#3B82F6)', color: '#fff', padding: '14px 26px', borderRadius: 999, fontWeight: 700, fontSize: 14, boxShadow: '0 0 26px rgba(139,92,246,0.35)' }}>Book a Strategy Call →</a>
      </div>
    </div>
  );
}

/* ---------- contact ---------- */

function pillStyle(active) {
  return {
    padding: '9px 14px', borderRadius: 999, fontSize: 12, fontWeight: 600, cursor: 'pointer',
    background: active ? 'linear-gradient(135deg,#8B5CF6,#3B82F6)' : '#1A1B26',
    border: active ? '1px solid transparent' : '1px solid rgba(255,255,255,0.08)',
    color: active ? '#fff' : '#9CA3AF'
  };
}
function needStyle(active) {
  return {
    display: 'flex', alignItems: 'center', gap: 8, padding: '9px 12px', borderRadius: 8, fontSize: 12, cursor: 'pointer',
    background: active ? 'rgba(139,92,246,0.12)' : '#1A1B26',
    border: active ? '1px solid rgba(139,92,246,0.4)' : '1px solid rgba(255,255,255,0.08)',
    color: active ? '#fff' : '#9CA3AF'
  };
}
const inputStyle = { width: '100%', boxSizing: 'border-box', background: '#1A1B26', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 10, padding: '12px 14px', color: '#fff', fontSize: 13, outline: 'none', marginBottom: 12 };

const CONTACT_FORM_INITIAL = { first: '', last: '', email: '', website: '', ig: '', situation: '', revenue: '', budget: '', needs: [], botcheck: '' };

function Contact() {
  const [ref, revealed] = useReveal();
  const [form, setForm] = useState(CONTACT_FORM_INITIAL);
  const [status, setStatus] = useState('idle'); // idle | loading | success | error
  const [errorMsg, setErrorMsg] = useState('');

  const set = (key) => (e) => setForm((s) => ({ ...s, [key]: e.target.value }));
  const setPill = (key, val) => () => setForm((s) => ({ ...s, [key]: val }));
  const toggleNeed = (val) => () => setForm((s) => ({
    ...s,
    needs: s.needs.includes(val) ? s.needs.filter((x) => x !== val) : [...s.needs, val]
  }));

  const validateForm = () => {
    if (!form.first.trim()) return 'Please enter your first name.';
    if (!form.last.trim()) return 'Please enter your last name.';
    if (!form.email.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email.trim())) return 'Please enter a valid email address.';
    if (!form.website.trim()) return 'Please enter your website URL.';
    if (!form.situation) return 'Please select your current situation.';
    if (!form.revenue) return 'Please select your monthly revenue.';
    if (form.needs.length === 0) return 'Please select at least one thing you need help with.';
    if (!form.budget) return 'Please select your budget range.';
    return '';
  };

  const handleSubmit = async () => {
    if (status === 'loading') return; // prevent duplicate submissions
    if (form.botcheck) return; // honeypot tripped — silently drop

    const validationError = validateForm();
    if (validationError) {
      setStatus('error');
      setErrorMsg(validationError);
      return;
    }

    setStatus('loading');
    setErrorMsg('');

    try {
      const res = await fetch(WEB3FORMS_ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
        body: JSON.stringify({
          access_key: WEB3FORMS_ACCESS_KEY,
          subject: 'New Growth Audit Application — Emmanuel Scale Growth OS',
          from_name: (form.first.trim() + ' ' + form.last.trim()).trim(),
          replyto: form.email.trim(),
          botcheck: false,
          'First Name': form.first.trim(),
          'Last Name': form.last.trim(),
          'Email Address': form.email.trim(),
          'Website URL': form.website.trim(),
          'Instagram': form.ig.trim() || 'Not provided',
          'Current Situation': form.situation,
          'Monthly Revenue': form.revenue,
          'What They Need Help With': form.needs.join(', '),
          'Budget Range': form.budget,
        }),
      });
      const data = await res.json().catch(() => ({}));
      if (res.ok && data.success) {
        setStatus('success');
        setForm(CONTACT_FORM_INITIAL);
      } else {
        setStatus('error');
        setErrorMsg((data && data.message) || 'Something went wrong sending your application. Please try again.');
      }
    } catch (e) {
      setStatus('error');
      setErrorMsg('Network error — please check your connection and try again.');
    }
  };

  return (
    <div id="contact" ref={ref} className={'contact-grid reveal flex flex-col lg:flex-row gap-14 items-start ' + (revealed ? 'reveal-shown' : 'reveal-hidden')} style={{ maxWidth: 1300, margin: '0 auto', padding: '70px 24px' }}>
      <div style={{ flex: 1 }}>
        <div style={{ color: '#A78BFA', fontSize: 12, fontWeight: 700, letterSpacing: '0.1em', marginBottom: 14 }}>I WORK WITH SERIOUS FOUNDERS</div>
        <h2 style={{ fontSize: 32, fontWeight: 800, lineHeight: 1.25, marginBottom: 18 }}>Ready To Turn Your Store Into A <GradientText>Revenue Machine?</GradientText></h2>
        <p style={{ color: '#9CA3AF', fontSize: 15, lineHeight: 1.7, marginBottom: 26 }}>Tell me a bit about your store and where you want it to go. I read every application myself.</p>
        <div className="flex flex-wrap gap-3.5" style={{ marginBottom: 26 }}>
          <a href="#contact-form" className="btn-primary" style={{ background: 'linear-gradient(135deg,#8B5CF6,#3B82F6)', color: '#fff', padding: '14px 24px', borderRadius: 999, fontWeight: 700, fontSize: 14, boxShadow: '0 0 26px rgba(139,92,246,0.35)' }}>Apply For Free Growth Audit →</a>
          <a href="https://upwork.com" target="_blank" rel="noreferrer" className="btn-outline" style={{ border: '1px solid rgba(255,255,255,0.16)', color: '#fff', padding: '14px 24px', borderRadius: 999, fontWeight: 700, fontSize: 14 }}>Hire Me on Upwork</a>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5" style={{ marginBottom: 22 }}>
          {CONTACT_CHECKLIST.map((cc, i) => (
            <div key={i} className="flex gap-2" style={{ color: '#9CA3AF', fontSize: 13 }}><span style={{ color: '#4ADE80' }}>✓</span>{cc}</div>
          ))}
        </div>
        <div style={{ background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 12, padding: 16, fontSize: 13, color: '#9CA3AF' }}>Not for you if you're looking for a quick logo-and-launch job with no ongoing optimization — this is a growth partnership, not a one-off gig.</div>
      </div>
      <div id="contact-form" style={{ flex: 1, width: '100%', background: '#12131C', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 20, padding: 32 }}>
        {status === 'success' ? (
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', textAlign: 'center', padding: '48px 12px' }}>
            <div style={{ width: 56, height: 56, borderRadius: '50%', background: 'linear-gradient(135deg,#8B5CF6,#3B82F6)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 26, marginBottom: 20, boxShadow: '0 0 26px rgba(139,92,246,0.35)' }}>✓</div>
            <div style={{ fontSize: 22, fontWeight: 800, marginBottom: 10 }}>Application received.</div>
            <div style={{ color: '#9CA3AF', fontSize: 14, lineHeight: 1.7, maxWidth: 360 }}>Thanks — I've received your growth audit application and will review your store personally. I'll get back to you within 24 hours.</div>
          </div>
        ) : (
          <React.Fragment>
            <input type="text" name="botcheck" value={form.botcheck} onChange={set('botcheck')} tabIndex={-1} autoComplete="off" aria-hidden="true" style={{ position: 'absolute', left: '-9999px', width: 1, height: 1, opacity: 0 }} />
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3" style={{ marginBottom: 12 }}>
              <input name="first_name" placeholder="First name" value={form.first} onChange={set('first')} style={{ ...inputStyle, marginBottom: 0 }} />
              <input name="last_name" placeholder="Last name" value={form.last} onChange={set('last')} style={{ ...inputStyle, marginBottom: 0 }} />
            </div>
            <input name="email" type="email" placeholder="Email address" value={form.email} onChange={set('email')} style={inputStyle} />
            <input name="website_url" placeholder="Website URL" value={form.website} onChange={set('website')} style={inputStyle} />
            <input name="instagram" placeholder="Instagram (optional)" value={form.ig} onChange={set('ig')} style={inputStyle} />
            <select name="current_situation" value={form.situation} onChange={set('situation')} style={{ ...inputStyle, color: form.situation ? '#fff' : '#9CA3AF', marginBottom: 16 }}>
              <option value="">Current situation…</option>
              {SITUATION_OPTIONS.map((so) => <option key={so} value={so}>{so}</option>)}
            </select>

            <div style={{ color: '#9CA3AF', fontSize: 12, fontWeight: 600, marginBottom: 8 }}>MONTHLY REVENUE</div>
            <div className="flex gap-2 flex-wrap" style={{ marginBottom: 16 }}>
              {REVENUE_OPTIONS.map((label) => (
                <div key={label} onClick={setPill('revenue', label)} style={pillStyle(form.revenue === label)}>{label}</div>
              ))}
            </div>

            <div style={{ color: '#9CA3AF', fontSize: 12, fontWeight: 600, marginBottom: 8 }}>WHAT DO YOU NEED HELP WITH?</div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-1.5" style={{ marginBottom: 16 }}>
              {NEEDS_OPTIONS.map((label) => {
                const active = form.needs.includes(label);
                return (
                  <div key={label} onClick={toggleNeed(label)} style={needStyle(active)}><span>{active ? '☑' : '☐'}</span>{label}</div>
                );
              })}
            </div>

            <div style={{ color: '#9CA3AF', fontSize: 12, fontWeight: 600, marginBottom: 8 }}>BUDGET RANGE</div>
            <div className="flex gap-2 flex-wrap" style={{ marginBottom: 22 }}>
              {BUDGET_OPTIONS.map((label) => (
                <div key={label} onClick={setPill('budget', label)} style={pillStyle(form.budget === label)}>{label}</div>
              ))}
            </div>

            {status === 'error' && errorMsg && (
              <div style={{ color: '#F87171', fontSize: 13, marginBottom: 14, textAlign: 'center' }}>{errorMsg}</div>
            )}

            <div
              onClick={handleSubmit}
              className="btn-primary"
              style={{
                width: '100%', boxSizing: 'border-box', textAlign: 'center',
                background: 'linear-gradient(135deg,#8B5CF6,#3B82F6)', color: '#fff', padding: 15, borderRadius: 999,
                fontWeight: 700, fontSize: 14,
                cursor: status === 'loading' ? 'not-allowed' : 'pointer',
                opacity: status === 'loading' ? 0.75 : 1,
                pointerEvents: status === 'loading' ? 'none' : 'auto',
                boxShadow: '0 0 26px rgba(139,92,246,0.35)'
              }}
            >
              {status === 'loading' ? 'Submitting…' : 'Submit Application'}
            </div>
          </React.Fragment>
        )}
      </div>
    </div>
  );
}

