/* ---------- case study detail system: shared bits ---------- */

function csDiagStatusStyle(status) {
  if (status === "Needs Work") return { color: "#F87171", bg: "rgba(248,113,113,0.12)" };
  if (status === "Opportunity") return { color: "#FBBF24", bg: "rgba(251,191,36,0.12)" };
  if (status === "Strong") return { color: "#4ADE80", bg: "rgba(74,222,128,0.12)" };
  return { color: "#60A5FA", bg: "rgba(96,165,250,0.12)" };
}

function CSLightbox({ src, alt, onClose }) {
  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);
  return ReactDOM.createPortal(
    <div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(6,6,10,0.92)", backdropFilter: "blur(6px)", zIndex: 200, display: "flex", alignItems: "center", justifyContent: "center", padding: 24, cursor: "zoom-out" }}>
      <img src={src} alt={alt} style={{ maxWidth: "92vw", maxHeight: "88vh", borderRadius: 12, boxShadow: "0 20px 60px rgba(0,0,0,0.5)", display: "block" }} onClick={(e) => e.stopPropagation()} />
      <button onClick={onClose} aria-label="Close" style={{ position: "absolute", top: 20, right: 20, width: 40, height: 40, borderRadius: "50%", background: "rgba(255,255,255,0.08)", border: "1px solid rgba(255,255,255,0.16)", color: "#fff", fontSize: 18, cursor: "pointer" }}>✕</button>
    </div>,
    document.body
  );
}

function CSStickyNav({ prevProject, nextProject }) {
  const ids = CS_SECTION_NAV.map((s) => s.id);
  const active = useActiveSection(ids);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const onScroll = () => {
      const h = document.documentElement;
      const max = h.scrollHeight - h.clientHeight;
      setProgress(max > 0 ? Math.min(100, (h.scrollTop / max) * 100) : 0);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const goTo = (id) => (e) => {
    e.preventDefault();
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  return (
    <div className="sticky" style={{ top: 62, zIndex: 40, background: "rgba(10,10,15,0.92)", backdropFilter: "blur(12px)", borderBottom: "1px solid rgba(255,255,255,0.08)" }}>
      <div style={{ height: 2, background: "rgba(255,255,255,0.06)" }}>
        <div style={{ height: "100%", width: progress + "%", background: "linear-gradient(90deg,#8B5CF6,#3B82F6)", transition: "width .1s linear" }} />
      </div>
      <div className="flex items-center justify-between gap-4" style={{ maxWidth: 1300, margin: "0 auto", padding: "10px 24px", overflowX: "auto" }}>
        <div className="flex items-center gap-1.5 flex-shrink-0">
          {CS_SECTION_NAV.map((s) => (
            <a key={s.id} href={"#" + s.id} onClick={goTo(s.id)} style={{
              padding: "6px 12px", borderRadius: 999, fontSize: 12, fontWeight: 600, whiteSpace: "nowrap",
              color: active === s.id ? "#fff" : "#9CA3AF",
              background: active === s.id ? "#1A1B26" : "transparent"
            }}>{s.label}</a>
          ))}
        </div>
        <div className="hidden sm:flex items-center gap-3 flex-shrink-0">
          {prevProject ? <a href={"#" + prevProject.slug} className="nav-link" style={{ fontSize: 12.5, fontWeight: 600, color: "#9CA3AF" }}>← {prevProject.name}</a> : null}
          <a href="#case-studies" className="nav-link" style={{ fontSize: 12.5, fontWeight: 600, color: "#9CA3AF" }}>All Case Studies</a>
          {nextProject ? <a href={"#" + nextProject.slug} className="nav-link" style={{ fontSize: 12.5, fontWeight: 600, color: "#9CA3AF" }}>{nextProject.name} →</a> : null}
        </div>
      </div>
    </div>
  );
}

