function CaseStudyDetailPage({ slug }) {
  const project = SELECTED_WORK.find((p) => p.slug === slug);
  const detail = CASE_STUDY_DETAIL[slug];
  if (!project || !detail) return <CaseStudyStubPage slug={slug} />;

  const idx = SELECTED_WORK.findIndex((p) => p.slug === slug);
  const prevProject = idx > 0 ? SELECTED_WORK[idx - 1] : null;
  const nextProject = idx < SELECTED_WORK.length - 1 ? SELECTED_WORK[idx + 1] : null;

  const [lightbox, setLightbox] = useState(false);

  return (
    <SubpageChrome>
      <CSStickyNav prevProject={prevProject} nextProject={nextProject} />
      <CSHero project={project} detail={detail} onImgClick={() => setLightbox(true)} />
      <CSSituation detail={detail} />
      <CSDiagnosisDashboard groupLabel={detail.diagnosisLabel} items={detail.diagnosis} />
      <CSApproach steps={detail.approach} />
      <CSTransformation project={project} detail={detail} onImgClick={() => setLightbox(true)} />
      <CSChangedGrid items={detail.changedGrid} />
      <CSImpact items={detail.impact} />
      <CSRecommendation quote={detail.recommendationQuote} whereNext={detail.recommendationWhereNext} />
      <CSYourStore intro={detail.yourStoreIntro} cards={detail.yourStoreCards} />
      <CSLessons items={detail.lessons} />
      <CSFinalCTA />
      <CSBottomNav prevProject={prevProject} nextProject={nextProject} />
      {lightbox ? <CSLightbox src={project.img} alt={project.name} onClose={() => setLightbox(false)} /> : null}
    </SubpageChrome>
  );
}

