/* ---------- shopify store setup page: section 7 before/after + live metrics ---------- */

function SSSBeforeAfterSlider({ rows }) {
  const [pos, setPos] = useState(50);
  const containerRef = useRef(null);
  const draggingRef = useRef(false);

  const updateFromClientX = (clientX) => {
    const el = containerRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    let pct = ((clientX - rect.left) / rect.width) * 100;
    pct = Math.max(0, Math.min(100, pct));
    setPos(pct);
  };

  useEffect(() => {
    const onMove = (e) => {
      if (!draggingRef.current) return;
      const clientX = e.touches ? e.touches[0].clientX : e.clientX;
      updateFromClientX(clientX);
    };
    const onUp = () => { draggingRef.current = false; };
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    window.addEventListener('touchmove', onMove, { passive: true });
    window.addEventListener('touchend', onUp);
    return () => {
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
      window.removeEventListener('touchmove', onMove);
      window.removeEventListener('touchend', onUp);
    };
  }, []);

  const rowStyle = { display: 'flex', justifyContent: 'space-between', padding: '14px 0', borderTop: '1px solid rgba(255,255,255,0.06)' };

  return (
    <div>
      <div ref={containerRef} style={{ position: 'relative', borderRadius: 16, overflow: 'hidden', background: '#12131C', border: '1px solid rgba(255,255,255,0.08)', userSelect: 'none', minHeight: 260 }}>
        <div style={{ padding: '52px 28px 20px' }}>
          {rows.map((r) => (
            <div key={r.label} style={rowStyle}>
              <span style={{ color: '#9CA3AF', fontSize: 14 }}>{r.label}</span>
              <span style={{ color: '#4ADE80', fontWeight: 700, fontSize: 15 }}>{r.after}</span>
            </div>
          ))}
        </div>
        <div style={{ position: 'absolute', top: 16, right: 20, fontSize: 11, fontWeight: 700, color: '#4ADE80', background: 'rgba(74,222,128,0.1)', padding: '4px 10px', borderRadius: 999 }}>AFTER</div>

        <div style={{ position: 'absolute', inset: 0, background: '#12131C', clipPath: 'inset(0 ' + (100 - pos) + '% 0 0)' }}>
          <div style={{ padding: '52px 28px 20px' }}>
            {rows.map((r) => (
              <div key={r.label} style={rowStyle}>
                <span style={{ color: '#9CA3AF', fontSize: 14 }}>{r.label}</span>
                <span style={{ color: '#F87171', fontWeight: 700, fontSize: 15 }}>{r.before}</span>
              </div>
            ))}
          </div>
          <div style={{ position: 'absolute', top: 16, left: 20, fontSize: 11, fontWeight: 700, color: '#F87171', background: 'rgba(248,113,113,0.1)', padding: '4px 10px', borderRadius: 999 }}>BEFORE</div>
        </div>

        <div className="slider-handle"
          onMouseDown={(e) => { draggingRef.current = true; updateFromClientX(e.clientX); }}
          onTouchStart={(e) => { draggingRef.current = true; updateFromClientX(e.touches[0].clientX); }}
          style={{ position: 'absolute', top: 0, bottom: 0, left: pos + '%' }}>
          <div style={{ position: 'absolute', top: 0, bottom: 0, left: -1, width: 2, background: 'linear-gradient(180deg,#8B5CF6,#3B82F6)' }} />
          <div style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%,-50%)', width: 38, height: 38, borderRadius: '50%', background: 'linear-gradient(135deg,#8B5CF6,#3B82F6)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', fontSize: 14, boxShadow: '0 4px 14px rgba(0,0,0,0.4)' }}>⇔</div>
        </div>
      </div>
      <div className="text-center" style={{ color: '#6B7280', fontSize: 12, marginTop: 14 }}>Drag the slider to compare before and after results</div>
    </div>
  );
}

