function SSSCaseStudy() {
  const [ref, revealed] = useReveal();
  const cases = [SSS_CASE];
  const [idx, setIdx] = useState(0);
  const c = cases[idx];
  return (
    <div ref={ref} className={'reveal ' + (revealed ? 'reveal-shown' : 'reveal-hidden')} style={{ maxWidth: 1100, margin: '0 auto', padding: '60px 24px' }}>
      <SSSSectionHeader eyebrow="CASE STUDIES" eyebrowColor="#60A5FA" heading="Real Results" />
      <div style={{ background: '#12131C', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 20, padding: 32 }}>
        <div className="flex items-center justify-between flex-wrap gap-3" style={{ marginBottom: 20 }}>
          <span style={{ color: '#A78BFA', fontSize: 13, fontWeight: 700, letterSpacing: '0.06em' }}>{c.label}</span>
          <span style={{ background: 'rgba(74,222,128,0.12)', color: '#4ADE80', fontSize: 12, fontWeight: 700, padding: '5px 12px', borderRadius: 999 }}>{c.badge}</span>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
          <div>
            <div style={{ color: '#9CA3AF', fontSize: 11, fontWeight: 700, letterSpacing: '0.06em', marginBottom: 8 }}>CHALLENGE</div>
            <div style={{ color: '#D1D5DB', fontSize: 13, lineHeight: 1.6 }}>{c.challenge}</div>
          </div>
          <div>
            <div style={{ color: '#9CA3AF', fontSize: 11, fontWeight: 700, letterSpacing: '0.06em', marginBottom: 8 }}>SOLUTION</div>
            <div style={{ color: '#D1D5DB', fontSize: 13, lineHeight: 1.6 }}>{c.solution}</div>
          </div>
          <div>
            <div style={{ color: '#9CA3AF', fontSize: 11, fontWeight: 700, letterSpacing: '0.06em', marginBottom: 8 }}>OUTCOME</div>
            <div className="flex flex-col gap-2.5">
              {c.outcome.map((o) => (
                <div key={o.label} style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 10, padding: '10px 12px' }}>
                  <div style={{ fontWeight: 800, fontSize: 16, color: '#4ADE80' }}>{o.value}</div>
                  <div style={{ color: '#6B7280', fontSize: 11 }}>{o.label}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
        <div className="flex items-center justify-center gap-4" style={{ marginTop: 26 }}>
          <button disabled={idx === 0} className="carousel-arrow" style={{ width: 34, height: 34, borderRadius: '50%', border: '1px solid rgba(255,255,255,0.12)', background: 'transparent', color: '#9CA3AF', fontSize: 15 }} onClick={() => setIdx((i) => Math.max(0, i - 1))} aria-label="Previous case study">‹</button>
          <div className="flex gap-2">
            {cases.map((_, i) => (
              <span key={i} style={{ width: 7, height: 7, borderRadius: '50%', background: i === idx ? '#8B5CF6' : 'rgba(255,255,255,0.15)' }} />
            ))}
          </div>
          <button disabled={idx === cases.length - 1} className="carousel-arrow" style={{ width: 34, height: 34, borderRadius: '50%', border: '1px solid rgba(255,255,255,0.12)', background: 'transparent', color: '#9CA3AF', fontSize: 15 }} onClick={() => setIdx((i) => Math.min(cases.length - 1, i + 1))} aria-label="Next case study">›</button>
        </div>
      </div>

      <div style={{ marginTop: 60 }}>
        <SSSSectionHeader eyebrow="TOOLS & PLATFORMS" eyebrowColor="#60A5FA" heading="Technology Stack" subtext="The tools I use to deliver this service. Hover any badge to learn more." />
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
          {SSS_TOOLS.map((t) => (
            <div key={t.name} className="tool-card" style={{ background: '#12131C', border: '1px solid rgba(255,255,255,0.08)', borderRadius: 14, padding: 18 }}>
              <div className="flex items-center gap-3">
                <div style={{ width: 34, height: 34, borderRadius: 9, background: 'linear-gradient(135deg,#8B5CF6,#3B82F6)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 15, flexShrink: 0 }}>{t.icon}</div>
                <div style={{ fontWeight: 700, fontSize: 14 }}>{t.name}</div>
              </div>
              <div className="tool-desc" style={{ color: '#9CA3AF', fontSize: 12, lineHeight: 1.5 }}>{t.desc}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

