function tfSeverityStyle(sev) {
  if (sev === 'Critical') return { color: '#F87171', bg: 'rgba(248,113,113,0.12)' };
  if (sev === 'High') return { color: '#F97316', bg: 'rgba(249,115,22,0.12)' };
  if (sev === 'Medium') return { color: '#FBBF24', bg: 'rgba(251,191,36,0.12)' };
  return { color: '#60A5FA', bg: 'rgba(96,165,250,0.12)' };
}
function tfStatusStyle(status) {
  if (status === 'Resolved') return { color: '#4ADE80', bg: 'rgba(74,222,128,0.12)' };
  if (status === 'Monitoring') return { color: '#60A5FA', bg: 'rgba(96,165,250,0.12)' };
  if (status === 'Investigating') return { color: '#FBBF24', bg: 'rgba(251,191,36,0.12)' };
  return { color: '#F87171', bg: 'rgba(248,113,113,0.12)' };
}

