/* ---------- router ---------- */

function normalizeHash() {
  return (window.location.hash || '').replace(/^#/, '');
}

function App() {
  const [hash, setHash] = useState(normalizeHash());

  useEffect(() => {
    const onHashChange = () => setHash(normalizeHash());
    window.addEventListener('hashchange', onHashChange);
    return () => window.removeEventListener('hashchange', onHashChange);
  }, []);

  const isServiceRoute = SERVICE_ROUTES.includes(hash);
  const isCaseStudyRoute = CASE_STUDY_ROUTES.includes(hash);

  useEffect(() => {
    if (isServiceRoute || isCaseStudyRoute) {
      window.scrollTo(0, 0);
    } else if (hash) {
      requestAnimationFrame(() => {
        const el = document.getElementById(hash);
        if (el) el.scrollIntoView({ behavior: 'smooth' });
      });
    } else {
      window.scrollTo(0, 0);
    }
  }, [hash, isServiceRoute, isCaseStudyRoute]);

  if (hash === 'shopify-store-setup') return <ShopifyStoreSetupPage />;
  if (hash === 'custom-store-design') return <CustomStoreDesignPage />;
  if (hash === 'dropshipping-strategy') return <DropshippingStrategyPage />;
  if (hash === 'paid-advertising') return <PaidAdvertisingPage />;
  if (hash === 'cro-optimization') return <CROOptimizationPage />;
  if (hash === 'email-retention') return <EmailRetentionPage />;
  if (hash === 'shopify-technical-fixing') return <ShopifyTechnicalFixingPage />;
  if (hash === 'seo-geo-aeo') return <SeoGeoAeoPage />;
  if (hash === 'analytics-tracking') return <AnalyticsTrackingPage />;
  if (isServiceRoute) return <ServiceStubPage slug={hash} />;
  if (isCaseStudyRoute) return <CaseStudyDetailPage slug={hash} key={hash} />;
  return <HomePage />;
}

ReactDOM.createRoot(document.getElementById('root')).render(<App />);
